<script setup lang="ts">
import { onMounted, ref, shallowRef } from 'vue';
import ContinueWatchingHero from '@/widgets/continue-watching/ContinueWatchingHero.vue';
import TitleGrid from '@/widgets/latest-releases/TitleGrid.vue';
import BaseSkeleton from '@/shared/ui/BaseSkeleton.vue';
import { fetchHome, searchTitles } from '@/entities/catalog/catalog.api';
import { PAGE_SIZE } from '@/shared/config/env';
import type { HomeData, Page, TitleListItem } from '@/shared/api/types';

const home = shallowRef<HomeData | null>(null);
const loading = ref(true);
const error = ref<string | null>(null);

const latestFetcher = (cursor?: string): Promise<Page<TitleListItem>> =>
  searchTitles({ sort: 'translation_date', cursor, limit: PAGE_SIZE });

onMounted(async () => {
  try {
    home.value = await fetchHome();
  } catch (e) {
    error.value = e instanceof Error ? e.message : 'Помилка завантаження';
  } finally {
    loading.value = false;
  }
});
</script>

<template>
  <div class="home">
    <template v-if="loading">
      <div class="home__hero-sk">
        <BaseSkeleton height="200px" radius="18px" />
      </div>
    </template>

    <ContinueWatchingHero v-else-if="home" :items="home.recentlyWatched" />

    <section class="home__releases">
      <h2 class="home__section-title">Актуальні релізи</h2>
      <TitleGrid :fetcher="latestFetcher" :initial="home?.latestReleases" />
    </section>

    <p v-if="error" class="home__error">{{ error }}</p>
  </div>
</template>

