import type { RecentlyWatched } from '@/shared/api/types';

const props = defineProps<{ items: RecentlyWatched[] }>();

const sliderEl = ref<HTMLElement | null>(null);

function scrollLeft(): void {
  sliderEl.value?.scrollBy({ left: -280 - 16, behavior: 'smooth' });
}

function scrollRight(): void {
  sliderEl.value?.scrollBy({ left: 280 + 16, behavior: 'smooth' });
}
</script>

