import { ref, type Ref } from 'vue';

interface PageResult<T> {
  items: T[];
  nextCursor: string | null;
}

/**
 * Keyset-paginated infinite list. Calls `fetcher(cursor)` and accumulates items
 * until `nextCursor` is null (Docs/Frontend-architecture.md §10).
 */
export function useInfiniteList<T>(fetcher: (cursor?: string) => Promise<PageResult<T>>) {
  const items = ref([]) as Ref<T[]>;
  const loading = ref(false);
  const done = ref(false);
  const error = ref<string | null>(null);
  let cursor: string | undefined;

  async function loadMore(): Promise<void> {
    if (loading.value || done.value) return;
    loading.value = true;
    error.value = null;
    try {
      const page = await fetcher(cursor);
      items.value.push(...page.items);
      cursor = page.nextCursor ?? undefined;
      if (!page.nextCursor) done.value = true;
    } catch (e) {
      error.value = e instanceof Error ? e.message : 'Помилка завантаження';
    } finally {
      loading.value = false;
    }
  }

  function reset(): void {
    items.value = [];
    cursor = undefined;
    done.value = false;
    error.value = null;
  }

  return { items, loading, done, error, loadMore, reset };
}
