<script setup lang="ts">
import { onMounted, ref } from 'vue';
import TitleCard from '@/shared/ui/TitleCard.vue';
import BasePoster from '@/shared/ui/BasePoster.vue';
import BaseSkeleton from '@/shared/ui/BaseSkeleton.vue';
import { useInfiniteList } from '@/shared/composables/useInfiniteList';
import { useIntersection } from '@/shared/composables/useIntersection';
import type { Page, TitleListItem } from '@/shared/api/types';

const props = defineProps<{
  fetcher: (cursor?: string) => Promise<Page<TitleListItem>>;
  /** Optional first page already loaded by the parent (avoids a double fetch). */
  initial?: Page<TitleListItem>;
}>();

const { items, loading, done, error, loadMore } = useInfiniteList<TitleListItem>(props.fetcher);
const sentinel = ref<Element | null>(null);

onMounted(() => {
  if (props.initial) {
    items.value.push(...props.initial.items);
    if (!props.initial.nextCursor) done.value = true;
  }
  if (items.value.length === 0) void loadMore();
});

useIntersection(sentinel, () => void loadMore());
</script>

<template>
  <div>
    <div class="grid">
      <TitleCard v-for="t in items" :key="t.id" :title="t" />
      <template v-if="loading">
        <div v-for="n in 6" :key="`sk-${n}`" class="grid__sk">
          <BasePoster :src="null" />
          <BaseSkeleton height="0.8rem" width="80%" />
        </div>
      </template>
    </div>

    <p v-if="error" class="grid__state">{{ error }}</p>
    <p v-else-if="done && items.length === 0" class="grid__state">Нічого не знайдено</p>
    <div ref="sentinel" class="grid__sentinel" />
  </div>
</template>

<style scoped>
.grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--sp-4) var(--sp-3);
  padding: var(--sp-4);
}
@media (min-width: 520px) {
  .grid {
    grid-template-columns: repeat(3, 1fr);
  }
}
@media (min-width: 768px) {
  .grid {
    grid-template-columns: repeat(4, 1fr);
  }
}
.grid__sk {
  display: flex;
  flex-direction: column;
  gap: var(--sp-2);
}
.grid__state {
  text-align: center;
  color: var(--text-faint);
  padding: var(--sp-6);
}
.grid__sentinel {
  height: 1px;
}
</style>
